  "headline": "Lamotrigine is not on FDA's shortage list as of 2026-10-21; Corvale East has 18.1 days on hand and Corvale General has 28.2 days on hand",
  "headline_cites": ["D3", "D1", "D2"],
  "sentences": [
    {
      "text": "FDA's drug shortage list shows lamotrigine is not listed as of 2026-10-21.",
      "cites": ["D3"]
    },
    {
      "text": "Corvale East holds 106 tablets of the 150 mg presentation with 5.8 tablets used per day, giving 18.1 days on hand.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale General holds 218 tablets of the same presentation with 7.7 tablets used per day, giving 28.2 days on hand.",
      "cites": ["D2"]
    },
    {
      "text": "The rule‑based check notes there are FDA actions or weak links but no action before a posting at a registered plant, so the buyer should verify current supply commitments.",
      "cites": ["D3", "D4"]
    },
    {
      "text": "The top ranked alternate manufacturer is Actavis Pharma, Inc., which is not on FDA's shortage list today.",
      "cites": ["D4"]
    },
    {
      "text": "Additional alternate manufacturers include Advagen Pharma Limited and Advanced Rx Pharmacy of Tennessee, LLC, also not on the shortage list.",
      "cites": ["D5", "D6"]
    },
    {
      "text": "Par Health, Inc. has a discontinuation posting for lamotrigine extended‑release tablets dated 2026-04-29, but this does not affect the immediate‑release product in use.",
      "cites": ["E11"]
    }
  ]
}
